define(['jquery','jquery-ui-modules/widget','mage/translate'],function($){'use strict';$.widget('mage.cards',{_create:function(){let options=this.options;let addCard=options.addCard;if(addCard){$(document).on('click',addCard,this._addCard.bind(this));}},_addCard:function(){window.location=this.options.addCardLocation;}});return $.mage.cards;});